const jobs = await browserjs(tabId, () => {
  const jobCards = Array.from(document.querySelectorAll('.job-tile, [data-job-id], .job'));
  if (jobCards.length > 0) {
    return jobCards.map(card => ({
      title: card.querySelector('h3, .job-title')?.textContent?.trim(),
      location: card.querySelector('.location-and-id, .location')?.textContent?.trim(),
      postedDate: card.querySelector('.posting-date, .posted-date')?.textContent?.trim(),
      updatedDate: card.querySelector('.updated-date')?.textContent?.trim(),
      description: card.querySelector('.description')?.textContent?.trim(),
      url: card.querySelector('a')?.href,
      fullText: card.innerText
    }));
  }

  // Fallback if specific classes aren't matched:
  const jobLinks = Array.from(document.querySelectorAll('h3 a'));
  return jobLinks.map(a => {
    const parent = a.closest('.job-tile') || a.parentElement?.parentElement;
    return {
      title: a.textContent?.trim(),
      url: a.href,
      text: parent?.innerText
    };
  });
});

