const result = await browserjs(tabId, async () => {
  const getMoreBtn = () => {
    const btns = Array.from(document.querySelectorAll('button'));
    return btns.find(b => b.textContent?.trim().toLowerCase() === 'more' || b.getAttribute('aria-label')?.includes('JOB CATEGORY'));
  };

  let count = 0;
  while (count < 10) {
    const btn = getMoreBtn();
    if (!btn || btn.disabled) break;
    btn.click();
    count++;
    await new Promise(r => setTimeout(r, 400));
  }

  // Now collect all categories in that fieldset
  const fieldsets = Array.from(document.querySelectorAll('fieldset, [role="group"]'));
  const catFieldset = fieldsets.find(f => /JOB CATEGORY/i.test(f.textContent || ''));
  if (!catFieldset) return { error: "not found" };
  const items = Array.from(catFieldset.querySelectorAll('button, label')).map(el => el.textContent?.trim());
  return { count, items };
});

console.log("Categories loaded:", result.count);
console.log("Category items:", result.items);
"}

