const searchInfo = await browserjs(tabId, () => {
  // Find search header or count
  const countHeading = document.querySelector('.search-results-count, [class*="results-count"], h1, h2');
  const countText = Array.from(document.querySelectorAll('*')).find(el => /\b(\d+)\s+jobs?\b/i.test(el.textContent || '') && el.children.length === 0)?.textContent;

