    const link = t.querySelector('a')?.href;
    const locAndId = t.querySelector('.location-and-id')?.innerText?.trim();
    const postedDate = t.querySelector('.posting-date')?.innerText?.trim();
    const updatedDate = t.querySelector('.updated-time, .updated-date, [class*="update"]')?.innerText?.trim();
    const qual = t.querySelector('.qualifications')?.innerText?.trim();
    return {
      index: idx + 1,
      title,
      link,
      locAndId,
      postedDate,
      updatedDate,
      qual
    };
  });

  return {
    countText,
    pagination,
    tilesCount: tiles.length,
    tiles
  };
});

