const testSort = await browserjs(tabId, async () => {
  // Let's check what jobs appear if sort=relevant
  const relevantUrl = "https://www.amazon.jobs/en/search?offset=0&result_limit=10&sort=relevant&category%5B%5D=medical-health-safety&job_type%5B%5D=Full-Time&country%5B%5D=USA&distanceType=Mi&radius=24km&industry_experience=one_to_three_years";
  const resRel = await fetch(relevantUrl);
  const textRel = await resRel.text();

  // And what jobs appear if sort=recent
  const recentUrl = "https://www.amazon.jobs/en/search?offset=0&result_limit=10&sort=recent&category%5B%5D=medical-health-safety&job_type%5B%5D=Full-Time&country%5B%5D=USA&distanceType=Mi&radius=24km&industry_experience=one_to_three_years";
  const resRec = await fetch(recentUrl);
  const textRec = await resRec.text();

  // Extract job titles or IDs from both
  const extractJobs = (html) => {
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');
    return Array.from(doc.querySelectorAll('.job-tile')).map(card => ({
      title: card.querySelector('h3')?.textContent?.trim(),
      id: card.querySelector('.location-and-id')?.textContent?.trim(),
      posted: card.querySelector('.posting-date')?.textContent?.trim(),
      updated: card.querySelector('.updated-time, .updated-date, [class*="update"]')?.textContent?.trim()
    }));
  };

  return {
    relevantJobs: extractJobs(textRel),
    recentJobs: extractJobs(textRec)
  };
});

console.log("Relevant vs Recent comparison:");
console.log("Relevant jobs:", JSON.stringify(testSort.relevantJobs.slice(0, 5), null, 2));
console.log("Recent jobs:", JSON.stringify(testSort.recentJobs.slice(0, 5), null, 2));

