      normalized_location: j.normalized_location,
      city: j.city,
      state: j.state,
      country_code: j.country_code,
      posted_date: j.posted_date,
      updated_time: j.updated_time,
      schedule_type_id: j.schedule_type_id,
      job_category: j.job_category,
      basic_qualifications: j.basic_qualifications,
      description: j.description?.slice(0, 200)
    }))
  };
});

console.log("Hits:", searchData.hits);
console.log("Count:", searchData.count);
console.log("Jobs length:", searchData.jobs?.length);
console.log(JSON.stringify(searchData.jobs?.slice(0, 5), null, 2));

