const tabId = 1148881640;

const moreJobs = await browserjs(tabId, async () => {
  const url = "https://www.amazon.jobs/en/search.json?category%5B%5D=medical-health-safety&schedule_type_id%5B%5D=Full-Time&normalized_country_code%5B%5D=USA&radius=24km&industry_experience[]=one_to_three_years&offset=0&result_limit=50&sort=recent";
  const resp = await fetch(url);
  const data = await resp.json();
  return data.jobs.map(j => ({
    id: j.id_icims,
    title: j.title,
    location: j.normalized_location || `${j.city}, ${j.state}`,
    posted_date: j.posted_date,
    updated_time: j.updated_time,
    basic_qualifications: j.basic_qualifications?.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
    job_path: j.job_path
  }));
});

console.log("Total jobs fetched:", moreJobs.length);
console.log("Date distribution:");
const dates = {};
moreJobs.forEach(j => {
  dates[j.posted_date] = (dates[j.posted_date] || 0) + 1;
});
console.log(dates);

// Print all jobs from September 17, 2026
const sept17Jobs = moreJobs.filter(j => j.posted_date.includes("September 17, 2026"));
console.log(`Jobs posted September 17, 2026 (${sept17Jobs.length}):`);
sept17Jobs.forEach((j, i) => {
  console.log(`${i + 1}. [Job ID: ${j.id}] ${j.title} - ${j.location} (Updated: ${j.updated_time})`);
});

