const tabId = 1148881640;

const jobDetails = await browserjs(tabId, async () => {
  const url = "https://www.amazon.jobs/en/search.json?category%5B%5D=medical-health-safety&schedule_type_id%5B%5D=Full-Time&normalized_country_code%5B%5D=USA&radius=24km&industry_experience[]=one_to_three_years&offset=0&result_limit=20&sort=recent";
  const resp = await fetch(url);
  const data = await resp.json();

  return data.jobs.map(j => ({
    id: j.id_icims,
    title: j.title.trim(),
    job_path: j.job_path,
    location: j.normalized_location || `${j.city}, ${j.state}, ${j.country_code}`,
    posted_date: j.posted_date,
    updated_time: j.updated_time,
    schedule_type: j.schedule_type_id,
    category: j.job_category,
    basic_qualifications: j.basic_qualifications?.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
    preferred_qualifications: j.preferred_qualifications?.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()
  }));
});

console.log("Top 10 jobs on page 1:");
jobDetails.slice(0, 10).forEach((j, i) => {
  console.log(`\n--- Job ${i + 1} ---`);
  console.log(`Title: ${j.title}`);
  console.log(`Job ID: ${j.id}`);
  console.log(`Location: ${j.location}`);
  console.log(`Posted Date: ${j.posted_date} (Updated: ${j.updated_time} ago)`);
  console.log(`Schedule: ${j.schedule_type}`);
  console.log(`Category: ${j.category}`);
  console.log(`Basic Qualifications: ${j.basic_qualifications?.slice(0, 200)}...`);
});

